<script>
    function copyText(id, place_id) {
        if (place_id == 3) {
            let el = document.getElementById('txt' + id);
            el.value = location.host + "/projects/micro-projects?tab=aleppo&projectA=" + id;
            el.style.display = 'block';
            el.select();
            el.focus();
            document.execCommand('copy');
            el.style.display = 'none';
        }
        else if (place_id == 1) {
            let el = document.getElementById('txt' + id);
            el.value = location.host + "/projects/micro-projects?tab=homs&projectH=" + id;
            el.style.display = 'block';
            el.select();
            el.focus();
            document.execCommand('copy');
            el.style.display = 'none';
        }
        else if (place_id == 2) {
            let el = document.getElementById('txt' + id);
            el.value = location.host + "/projects/micro-projects?tab=damascus&projectD=" + id;
            el.style.display = 'block';
            el.select();
            el.focus();
            document.execCommand('copy');
            el.style.display = 'none';
        }
        else if (place_id == 4) {
            let el = document.getElementById('txt' + id);
            el.value = location.host + "/projects/micro-projects?tab=latakia&projectL=" + id;
            el.style.display = 'block';
            el.select();
            el.focus();
            document.execCommand('copy');
            el.style.display = 'none';
        }
        else if (place_id == 7) {
