                else url2.searchParams.set('tab', 'aleppo');
                history.pushState({}, '', url2.href);
            }
            let s = url2.searchParams.get("search");
            let v = url2.searchParams.get("video");
            let input = document.getElementById('search-input');
            let searchvideo = document.getElementById('search-video');
            let searchsearch = document.getElementById('search-search');
            let switchsearch = document.getElementById('switchsearch');

            if (v === 'true') {
                searchvideo.src = "/images/ico/reverst-video.svg";
                switchvideo.style.background = '#BC1818';
            }
            else {
                searchvideo.src = "/images/ico/search-video-icon.svg";
                switchvideo.style.background = '#f7f7f7';
            }
            if (s === '' || s === null) {
                searchsearch.src = "/images/ico/search-icon.svg";
                switchsearch.style.background = '#f7f7f7';
            }
            else {
                searchsearch.src = "/images/ico/reverst-search.svg";
                switchsearch.style.background = '#BC1818';
            }
            input.value = s;
            $('input[rel="tooltip"]').tooltip();

            let tab = url2.searchParams.get("tab") + "Tab";
            let t = document.getElementById(tab);
            let tt = new bootstrap.Tab(t);
            tt.show();
            // set_time_limit(0);
            let projectA = url2.searchParams.get("projectA");
            let projectH = url2.searchParams.get("projectH");
            let projectD = url2.searchParams.get("projectD");
            let projectL = url2.searchParams.get("projectL");
            if (projectA != null) {
                setTimeout(() => {
                    $('#project-detail-copy').modal('show');
                }, 1000);
            }
            if (projectH != null) {
                setTimeout(() => {
                    $('#project-H-detail-copy').modal('show');
                }, 1000);
            }
            if (projectD != null) {
                setTimeout(() => {
                    $('#project-D-detail-copy').modal('show');
                }, 1000);
            }
            if (projectL != null) {
                setTimeout(() => {
                    $('#project-L-detail-copy').modal('show');
                }, 1000);
            }
        });
    }, 545 * 1.33);
</script>
